// Only this chat may give commands: telegram_chat_id in the data table codebot_settings
const ALLOWED_CHAT = String($input.all().map(i => i.json).find(r => r.key === 'telegram_chat_id')?.value ?? '').trim();
if (!ALLOWED_CHAT) throw new Error('telegram_chat_id is missing in codebot_settings');
// kind: list (/work)  |  command (/work <repo>)  |  pick (project button)  |  callback (yes/no)
// Input: { route, update } from CodeBot - Telegram Router
const inp = $('From router').first().json;
const u = inp.update || inp;
if (u.callback_query) {
  const cq = u.callback_query;
  const chat = String(cq.message?.chat?.id);
  if (chat !== ALLOWED_CHAT) return [];
  const data = String(cq.data || '');
  let m = data.match(/^p\|(.+)$/);
  if (m) return [{ json: { kind: 'pick', chat_id: chat, query_id: cq.id, arg: m[1] } }];
  m = data.match(/^w\|([yn])\|([^|]+)\|(\d+)$/);
  if (m) return [{ json: { kind: 'callback', chat_id: chat, message_id: cq.message.message_id,
                           query_id: cq.id, action: m[1], repo: m[2], number: Number(m[3]) } }];
  return [];
}
const msg = u.message;
if (!msg?.text || String(msg.chat?.id) !== ALLOWED_CHAT) return [];
const m = msg.text.trim().match(/^\/work(?:@\w+)?(?:\s+(\S+))?/i);
if (!m) return [];
const arg = m[1] || '';
return [{ json: { kind: arg ? 'command' : 'list', chat_id: String(msg.chat.id), arg } }];

// ==== ADJUST HERE ====
const SKIP_STATUS = ['Done', 'Paused', 'Someday'];          // don't offer these projects
// =======================
const rank = { High: 0, Medium: 1, Low: 2 };
const projects = $input.all().map(i => i.json)
  .filter(p => p.key && p.repo && !SKIP_STATUS.includes(p.status))
  .map(p => ({ name: p.name || p.key, key: String(p.key), repo: String(p.repo).trim(), prio: p.priority || 'Medium' }))
  .sort((a, b) => (rank[a.prio] ?? 1) - (rank[b.prio] ?? 1) || a.name.localeCompare(b.name, 'en'));

const bytes = s => new TextEncoder().encode(s).length;
const rows = [];
for (const p of projects) {
  const data = `p|${p.key}`;                     // Telegram allows at most 64 bytes
  if (bytes(data) > 64) continue;
  rows.push([{ text: `${p.key} · ${p.name}`, callback_data: data }]);
}
const payload = { chat_id: $('Router').first().json.chat_id,
                  text: rows.length ? 'What should Claude work on?' : 'No active projects found in codebot_projects.' };
if (rows.length) payload.reply_markup = { inline_keyboard: rows };
return [{ json: { payload } }];

// Resolve through codebot_projects: key, "owner/repo" or just "repo". Anything not in the list is not processed.
const arg = ($('Router').first().json.arg || '').trim();
const a = arg.toLowerCase();
let hit = null;
for (const p of $input.all().map(i => i.json)) {
  const r = String(p.repo || '').trim();
  if (!r || !p.key) continue;
  if (String(p.key).toLowerCase() === a || r.toLowerCase() === a || r.toLowerCase().split('/')[1] === a) { hit = p; break; }
}
if (!hit) return [{ json: { repo: null, owner: '', name: '', project: null, arg } }];
const repo = String(hit.repo).trim();
const [owner, name] = repo.split('/');
return [{ json: { repo, owner, name, project: hit.name, arg } }];

parameters.query:
=query {
  repository(owner: "{{ $json.owner }}", name: "{{ $json.name }}") {
    nameWithOwner
    pullRequests(states: OPEN, first: 50) { nodes { number url headRefName } }
    issues(first: 100, states: OPEN, orderBy: { field: CREATED_AT, direction: ASC }) {
      nodes { number title url body createdAt labels(first: 10) { nodes { name } } subIssues(first: 1) { totalCount } parent { number } blockedBy(first: 20) { nodes { number state } } closedByPullRequestsReferences(first: 5) { nodes { number state url } } }
    }
  }
}

